public List<Integer> dynamicArray(int n, int[][] queries) {
    List<int[]> log = new ArrayList<>();
    List<Integer> answers = new ArrayList<>();
    int lastAnswer = 0;
    for (int[] q : queries) {
        int idx = (q[1] ^ lastAnswer) % n;
        if (q[0] == 1) {
            log.add(new int[]{idx, q[2]});
        } else {
            List<Integer> seq = new ArrayList<>();
            for (int[] entry : log) {
                if (entry[0] == idx) seq.add(entry[1]);
            }
            lastAnswer = seq.get(q[2] % seq.size());
            answers.add(lastAnswer);
        }
    }
    return answers;
}

