def dynamic_array(n: int, queries: list[list[int]]) -> list[int]:
    log: list[tuple[int, int]] = []
    answers: list[int] = []
    last_answer = 0
    for typ, x, y in queries:
        idx = (x ^ last_answer) % n
        if typ == 1:
            log.append((idx, y))
        else:
            seq = [v for i, v in log if i == idx]
            last_answer = seq[y % len(seq)]
            answers.append(last_answer)
    return answers

