public List<Integer> dynamicArray(int n, int[][] queries) {
    List<List<Integer>> seq = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        seq.add(new ArrayList<>());
    }
    List<Integer> answers = new ArrayList<>();
    int lastAnswer = 0;
    for (int[] q : queries) {
        int idx = (q[1] ^ lastAnswer) % n;
        if (q[0] == 1) {
            seq.get(idx).add(q[2]);
        } else {
            List<Integer> target = seq.get(idx);
            lastAnswer = target.get(q[2] % target.size());
            answers.add(lastAnswer);
        }
    }
    return answers;
}

