def dynamic_array(n: int, queries: list[list[int]]) -> list[int]:
    seq: list[list[int]] = [[] for _ in range(n)]
    answers: list[int] = []
    last_answer = 0
    for typ, x, y in queries:
        idx = (x ^ last_answer) % n
        if typ == 1:
            seq[idx].append(y)
        else:
            target = seq[idx]
            last_answer = target[y % len(target)]
            answers.append(last_answer)
    return answers
